package dev.projectflint.system;

import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.gamerules.GameRules;

/**
 * Makes vanilla water finite by disabling source-block conversion for every
 * Project Flint world when the server starts. Existing lakes/rivers/oceans
 * remain intact, but removed source blocks are never regenerated by neighbors.
 */
public final class FiniteWaterSystem {
	private FiniteWaterSystem() {
	}

	public static void initialize() {
		ServerLifecycleEvents.SERVER_STARTED.register(FiniteWaterSystem::disableInfiniteWater);
	}

	private static void disableInfiniteWater(MinecraftServer server) {
		for (ServerLevel level : server.getAllLevels()) {
			GameRules rules = level.getGameRules();
			if (rules.get(GameRules.WATER_SOURCE_CONVERSION)) {
				rules.set(GameRules.WATER_SOURCE_CONVERSION, false, server);
			}
		}
	}
}
